import { createAdminClient, authenticateUser } from '../_shared/amazon/supabase.ts';
import { retryPendingAmazonTracking, syncAmazonTracking } from '../_shared/amazon/shipment-confirmation.ts';

const corsHeaders={
  'Access-Control-Allow-Origin':'*',
  'Access-Control-Allow-Headers':'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods':'POST, OPTIONS',
};
function response(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{...corsHeaders,'Content-Type':'application/json'}});}
function allowed(caller:any){const permissions=Array.isArray(caller?.permissions)?caller.permissions:[];return caller?.role==='admin'||permissions.includes('orders');}

Deno.serve(async(req:Request)=>{
  if(req.method==='OPTIONS')return new Response('ok',{headers:corsHeaders});
  if(req.method!=='POST')return response({error:'Método no permitido.'},405);
  try{
    const admin=createAdminClient(),caller=await authenticateUser(req,admin);if(!allowed(caller))return response({error:'No tienes permiso para gestionar pedidos.'},403);
    const body=await req.json().catch(()=>({})),action=String(body?.action||'confirm_order_tracking');
    if(action==='confirm_order_tracking'){
      const orderId=String(body?.orderId||'').trim();if(!orderId)return response({error:'Falta el pedido.'},400);
      const {data:order,error}=await admin.from('fulfillment_orders').select('*').eq('id',orderId).eq('owner_id',caller.data_owner_id).maybeSingle();if(error)throw error;if(!order)return response({error:'Pedido no encontrado.'},404);
      const rawOverride=body?.trackingOverride&&typeof body.trackingOverride==='object'?body.trackingOverride:null;
      const trackingOverride=rawOverride?{
        trackingNumber:rawOverride.trackingNumber==null?null:String(rawOverride.trackingNumber),
        trackingUrl:rawOverride.trackingUrl==null?null:String(rawOverride.trackingUrl),
        parcelId:rawOverride.parcelId??null,
        carrierCode:rawOverride.carrierCode==null?null:String(rawOverride.carrierCode),
        carrierName:rawOverride.carrierName==null?null:String(rawOverride.carrierName),
        shippingServiceName:rawOverride.shippingServiceName==null?null:String(rawOverride.shippingServiceName),
      }:undefined;
      const result=await syncAmazonTracking(admin,order,trackingOverride);return response({ok:true,...result});
    }
    if(action==='retry_pending'){
      const result=await retryPendingAmazonTracking(admin,caller.data_owner_id,Number(body?.limit)||5,Boolean(body?.force));return response({ok:true,...result});
    }
    return response({error:'Acción no válida.'},400);
  }catch(error){
    const message=error instanceof Error?error.message:String(error||'Error interno.');
    const status=/Sesión no válida/.test(message)?401:/permiso/i.test(message)?403:500;
    return response({error:message},status);
  }
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

import {claimOrderShipping,releaseOrderShipping} from '../orderCancellation.ts';
import { sanitizeAmazonError } from './http.ts';
import { spApiRequest } from './sp-api.ts';
import { loadAmazonSpApiCredentials, type AmazonSpApiCredentials } from './config.ts';

type FulfillmentOrderRow={
  id:string;owner_id:string;order_id?:string|null;order_number?:string|null;source_channel?:string|null;source_integration_account_id?:string|null;
  tracking_number?:string|null;sendcloud_parcel_id?:number|string|null;carrier_code?:string|null;carrier_name?:string|null;
  shipping_service_name?:string|null;label_created_at?:string|null;fulfilled_at?:string|null;tracking_updated_at?:string|null;
  order_updated_at?:string|null;amazon_tracking_synced_at?:string|null;amazon_tracking_sync_error?:string|null;
  amazon_tracking_sync_attempts?:number|null;amazon_tracking_last_attempt_at?:string|null;
};

type AmazonOrderContext={amazonOrderId:string;marketplaceId:string;amazonAccountId:string;orderItems:Array<{orderItemId:string;quantity:number}>};
export type AmazonTrackingSyncResult={orderId:string;amazonOrderId:string;status:'confirmed'|'already_synced';trackingNumber:string;packageReferenceId:string|null};
export type AmazonTrackingOverride={trackingNumber?:string|null;trackingUrl?:string|null;parcelId?:number|string|null;carrierCode?:string|null;carrierName?:string|null;shippingServiceName?:string|null;labelCreatedAt?:string|null};

function clean(value:unknown){return String(value??'').trim();}
function withTrackingOverride(order:FulfillmentOrderRow,override?:AmazonTrackingOverride):FulfillmentOrderRow{
  if(!override)return order;
  return {
    ...order,
    tracking_number:override.trackingNumber??order.tracking_number,
    sendcloud_parcel_id:override.parcelId??order.sendcloud_parcel_id,
    carrier_code:override.carrierCode??order.carrier_code,
    carrier_name:override.carrierName??order.carrier_name,
    shipping_service_name:override.shippingServiceName??order.shipping_service_name,
    label_created_at:override.labelCreatedAt??order.label_created_at,
  };
}
function amazonOrderId(order:FulfillmentOrderRow){
  const candidates=[order.order_id,order.order_number].map(clean).filter(Boolean);
  const found=candidates.find(value=>/^\d{3}-\d{7}-\d{7}$/.test(value));
  if(!found)throw new Error('El pedido no contiene un Amazon Order ID válido.');
  return found;
}
function positivePackageReference(value:unknown){const text=clean(value);return /^\d+$/.test(text)&&Number(text)>0?text:null;}
function attemptDue(order:FulfillmentOrderRow,now=Date.now()){
  if(!order.amazon_tracking_last_attempt_at)return true;
  const last=new Date(order.amazon_tracking_last_attempt_at).getTime();if(!Number.isFinite(last))return true;
  const previous=Math.max(0,Number(order.amazon_tracking_sync_attempts)||0);
  const delayMinutes=Math.min(60,Math.max(1,2**Math.min(previous,6)));
  return now-last>=delayMinutes*60_000;
}
function carrier(order:FulfillmentOrderRow){
  const raw=`${clean(order.carrier_code)} ${clean(order.carrier_name)} ${clean(order.shipping_service_name)}`.toLowerCase();
  if(raw.includes('mrw'))return {carrierCode:'MRW',carrierName:'MRW'};
  if(raw.includes('correos express'))return {carrierCode:'Correos Express',carrierName:'Correos Express'};
  if(raw.includes('correos'))return {carrierCode:'Correos',carrierName:'Correos'};
  if(raw.includes('seur'))return {carrierCode:'SEUR',carrierName:'SEUR'};
  if(raw.includes('gls'))return {carrierCode:'GLS',carrierName:'GLS'};
  if(raw.includes('ups'))return {carrierCode:'UPS',carrierName:'UPS'};
  if(raw.includes('dhl'))return {carrierCode:'DHL',carrierName:'DHL'};
  const name=clean(order.carrier_name)||clean(order.carrier_code)||'Transportista';
  return {carrierCode:'Other',carrierName:name};
}
async function claimAmazonTrackingAttempt(admin:any,order:FulfillmentOrderRow){
  const previous=Math.max(0,Number(order.amazon_tracking_sync_attempts)||0),now=new Date().toISOString();
  const {data,error}=await admin.from('fulfillment_orders')
    .update({amazon_tracking_last_attempt_at:now,amazon_tracking_sync_error:null,amazon_tracking_sync_attempts:previous+1})
    .eq('id',order.id)
    .eq('owner_id',order.owner_id)
    .is('amazon_tracking_synced_at',null)
    .eq('amazon_tracking_sync_attempts',previous)
    .select('*')
    .maybeSingle();
  if(error)throw error;
  return data as FulfillmentOrderRow|null;
}
async function currentTrackingState(admin:any,order:FulfillmentOrderRow){
  const {data,error}=await admin.from('fulfillment_orders')
    .select('amazon_tracking_synced_at,sendcloud_parcel_id')
    .eq('id',order.id)
    .eq('owner_id',order.owner_id)
    .maybeSingle();
  if(error)throw error;
  return data;
}
async function markSuccess(admin:any,order:FulfillmentOrderRow){
  const now=new Date().toISOString();
  const patch:any={amazon_tracking_synced_at:now,amazon_tracking_last_attempt_at:now,amazon_tracking_sync_error:null,source_status:'shipped'};
  if(!order.fulfilled_at)patch.fulfilled_at=now;
  const {error}=await admin.from('fulfillment_orders').update(patch).eq('id',order.id).eq('owner_id',order.owner_id);
  if(error)throw error;
}
async function markFailure(admin:any,order:FulfillmentOrderRow,errorValue:unknown){
  const now=new Date().toISOString(),message=sanitizeAmazonError(errorValue instanceof Error?errorValue.message:errorValue);
  const {error}=await admin.from('fulfillment_orders').update({amazon_tracking_last_attempt_at:now,amazon_tracking_sync_error:message}).eq('id',order.id).eq('owner_id',order.owner_id).is('amazon_tracking_synced_at',null);
  if(error)throw error;
}
async function loadContext(admin:any,order:FulfillmentOrderRow):Promise<AmazonOrderContext>{
  const orderId=amazonOrderId(order);
  let expectedAmazonAccountId='';
  if(order.source_integration_account_id){
    const {data:integration,error:integrationError}=await admin.from('integration_accounts')
      .select('linked_resource_id').eq('owner_id',order.owner_id).eq('provider','amazon').eq('id',order.source_integration_account_id).maybeSingle();
    if(integrationError)throw integrationError;
    expectedAmazonAccountId=clean(integration?.linked_resource_id);
  }
  let orderQuery=admin.from('amazon_orders').select('amazon_account_id,marketplace_id,fulfillment_channel')
    .eq('owner_id',order.owner_id).eq('amazon_order_id',orderId);
  if(expectedAmazonAccountId)orderQuery=orderQuery.eq('amazon_account_id',expectedAmazonAccountId);
  const {data:amazonRows,error:amazonError}=await orderQuery.limit(2);
  if(amazonError)throw amazonError;
  if(!amazonRows?.length)throw new Error(`Amazon todavía no ha sincronizado el pedido ${orderId}.`);
  if(amazonRows.length!==1)throw new Error(`El pedido ${orderId} aparece en más de una cuenta o marketplace de Amazon.`);
  const amazonAccountId=clean(amazonRows[0].amazon_account_id);if(!amazonAccountId)throw new Error(`El pedido ${orderId} no tiene cuenta Amazon asociada.`);
  const marketplaceId=clean(amazonRows[0].marketplace_id);if(!marketplaceId)throw new Error(`El pedido ${orderId} no tiene marketplace asociado.`);
  const {data:itemRows,error:itemError}=await admin.from('amazon_order_items').select('order_item_id,quantity_ordered')
    .eq('owner_id',order.owner_id).eq('amazon_account_id',amazonAccountId).eq('amazon_order_id',orderId).eq('marketplace_id',marketplaceId).gt('quantity_ordered',0);
  if(itemError)throw itemError;
  const orderItems=(itemRows||[]).map((item:any)=>({orderItemId:clean(item.order_item_id),quantity:Math.max(1,Math.trunc(Number(item.quantity_ordered)||0))})).filter((item:any)=>item.orderItemId);
  if(!orderItems.length)throw new Error(`Amazon todavía no ha sincronizado las líneas del pedido ${orderId}.`);
  return {amazonOrderId:orderId,marketplaceId,amazonAccountId,orderItems};
}
async function currentPackages(orderId:string,credentials:AmazonSpApiCredentials){
  const data:any=await spApiRequest(`/orders/2026-01-01/orders/${encodeURIComponent(orderId)}`,{query:{includedData:['PACKAGES']}},credentials);
  const current=data?.order||data?.Order||data||{};
  return Array.isArray(current?.packages)?current.packages:[];
}
function packageReference(packages:any[],trackingNumber:string,legacyParcelId:unknown){
  const exact=packages.filter(item=>clean(item?.trackingNumber)===trackingNumber);
  if(exact.length){
    const ref=positivePackageReference(exact[0]?.packageReferenceId);
    if(!ref)throw new Error('Amazon devolvió un packageReferenceId no numérico para el tracking existente.');
    return {packageReferenceId:ref,alreadySynced:true};
  }
  if(packages.length===1){
    const ref=positivePackageReference(packages[0]?.packageReferenceId);
    if(!ref)throw new Error('Amazon devolvió un packageReferenceId no numérico para el paquete existente.');
    return {packageReferenceId:ref,alreadySynced:false};
  }
  if(packages.length>1)throw new Error('Amazon tiene varios paquetes para este pedido y ZENVIA no puede determinar de forma segura cuál corresponde al tracking.');
  const legacy=positivePackageReference(legacyParcelId);
  return {packageReferenceId:legacy||'1',alreadySynced:false};
}

export async function syncAmazonTracking(admin:any,order:FulfillmentOrderRow,override?:AmazonTrackingOverride):Promise<AmazonTrackingSyncResult>{
  const requested=withTrackingOverride(order,override);
  const trackingNumber=clean(requested.tracking_number);if(requested.source_channel!=='amazon')throw new Error('El pedido no procede de Amazon.');if(!trackingNumber)throw new Error('El pedido todavía no tiene número de seguimiento.');
  const shippingClaim=await claimOrderShipping(admin,requested);
  try{
  const claimedRow=await claimAmazonTrackingAttempt(admin,requested);
  const claimed=claimedRow?withTrackingOverride(claimedRow,override):null;
  if(!claimed){
    const state=await currentTrackingState(admin,order);
    if(state?.amazon_tracking_synced_at)return {orderId:requested.id,amazonOrderId:amazonOrderId(requested),status:'already_synced',trackingNumber,packageReferenceId:positivePackageReference(state.sendcloud_parcel_id??requested.sendcloud_parcel_id)||null};
    throw new Error('La confirmación del tracking de Amazon ya está en curso.');
  }
  let context:AmazonOrderContext|undefined;
  try{
    context=await loadContext(admin,claimed);
    const credentials=await loadAmazonSpApiCredentials(admin,{amazonAccountId:context.amazonAccountId,integrationAccountId:claimed.source_integration_account_id,ownerId:claimed.owner_id});
    const packages=await currentPackages(context.amazonOrderId,credentials);
    const selectedPackage=packageReference(packages,trackingNumber,claimed.sendcloud_parcel_id);
    if(selectedPackage.alreadySynced){await markSuccess(admin,claimed);return {orderId:claimed.id,amazonOrderId:context.amazonOrderId,status:'already_synced',trackingNumber,packageReferenceId:selectedPackage.packageReferenceId};}
    const carrierData=carrier(claimed),shipDate=claimed.label_created_at||claimed.fulfilled_at||claimed.tracking_updated_at||claimed.order_updated_at||new Date().toISOString();
    const packageDetail:any={packageReferenceId:selectedPackage.packageReferenceId,carrierCode:carrierData.carrierCode,carrierName:carrierData.carrierName,trackingNumber,shipDate:new Date(shipDate).toISOString(),orderItems:context.orderItems};
    const shippingMethod=clean(claimed.shipping_service_name);if(shippingMethod)packageDetail.shippingMethod=shippingMethod;
    await spApiRequest(`/orders/v0/orders/${encodeURIComponent(context.amazonOrderId)}/shipmentConfirmation`,{method:'POST',body:{marketplaceId:context.marketplaceId,packageDetail}},credentials);
    await markSuccess(admin,claimed);
    return {orderId:claimed.id,amazonOrderId:context.amazonOrderId,status:'confirmed',trackingNumber,packageReferenceId:selectedPackage.packageReferenceId};
  }catch(error){
    try{await markFailure(admin,claimed,error)}catch{/* preserve original Amazon error */}
    throw error;
  }
  }finally{await releaseOrderShipping(admin,shippingClaim);}
}

export async function retryPendingAmazonTracking(admin:any,ownerId:string,limit=5,force=false){
  const safeLimit=Math.max(1,Math.min(25,Math.trunc(Number(limit)||5)));
  let query=admin.from('fulfillment_orders').select('*').eq('owner_id',ownerId).eq('source_channel','amazon').not('tracking_number','is',null).is('amazon_tracking_synced_at',null);
  if(!force)query=query.gt('amazon_tracking_sync_attempts',0);
  const {data,error}=await query.order('amazon_tracking_last_attempt_at',{ascending:true,nullsFirst:false}).limit(Math.max(safeLimit*4,20));
  if(error)throw error;
  const results:any[]=[];
  for(const order of data||[]){
    if(results.length>=safeLimit)break;
    if(!force&&!attemptDue(order))continue;
    try{const result=await syncAmazonTracking(admin,order);results.push({...result,ok:true})}
    catch(syncError){results.push({orderId:order.id,ok:false,error:sanitizeAmazonError(syncError instanceof Error?syncError.message:syncError)})}
  }
  return {attempted:results.length,succeeded:results.filter(item=>item.ok).length,failed:results.filter(item=>!item.ok).length,results};
}

const cancellationReasons:any={customer:{amazon:'BuyerCanceled',shopify:'CUSTOMER'},inventory:{amazon:'NoInventory',shopify:'INVENTORY'},address:{amazon:'ShippingAddressUndeliverable',shopify:'OTHER'},other:{amazon:'GeneralAdjustment',shopify:'OTHER'}};
function reason(value:string){const found=cancellationReasons[value];if(!found)throw new Error('Motivo de cancelación no válido.');return found;}
function xmlEscape(value:string){return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&apos;');}
export function amazonCancellationXml(sellerId:string,orderId:string,itemIds:string[],reasonKey:string){
 if(!/^\d{3}-\d{7}-\d{7}$/.test(orderId)||!sellerId||!itemIds.length)throw new Error('Faltan los identificadores del pedido Amazon.');
 return `<?xml version="1.0" encoding="UTF-8"?><AmazonEnvelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="amzn-envelope.xsd"><Header><DocumentVersion>1.01</DocumentVersion><MerchantIdentifier>${xmlEscape(sellerId)}</MerchantIdentifier></Header><MessageType>OrderAcknowledgement</MessageType><Message><MessageID>1</MessageID><OrderAcknowledgement><AmazonOrderID>${xmlEscape(orderId)}</AmazonOrderID><StatusCode>Failure</StatusCode>${itemIds.map(id=>`<Item><AmazonOrderItemCode>${xmlEscape(id)}</AmazonOrderItemCode><CancelReason>${reason(reasonKey).amazon}</CancelReason></Item>`).join('')}</OrderAcknowledgement></Message></AmazonEnvelope>`;
}
export function shopifyCancellationInput(orderId:string,options:any){
 if(!/^gid:\/\/shopify\/Order\/\d+$/.test(orderId))throw new Error('Identificador Shopify no válido.');
 return {orderId,reason:reason(options.reason).shopify,notifyCustomer:false,refundMethod:{originalPaymentMethodsRefund:options.refund===true},restock:options.restock!==false};
}
export function carrierCancellationResult(provider:string,payload:any){
 if(provider==='envia'&&payload?.meta==='error')throw new Error(payload.error?.message||payload.error?.description||'Envia.com rechazó la cancelación.');
 const data=Array.isArray(payload?.data)?payload.data[0]:payload?.data||payload;
 const status=String(data?.status||payload?.status||'').toLowerCase();
 if(['cancelled','canceled','success','confirmed'].includes(status)||data?.cancelled===true||data?.canceled===true)return {status:'confirmed',message:'El transportista aceptó la anulación.'};
 if(['pending','cancellation_requested','cancellation_pending','requested','in_progress'].includes(status))return {status:'pending',message:'Anulación solicitada; pendiente de confirmación del transportista.'};
 if(['error','failed','rejected'].includes(status)||data?.cancelled===false)throw new Error(data?.message||payload?.message||'El transportista rechazó la anulación.');
 return {status:'unknown',message:'La respuesta no confirma la anulación. Comprueba el estado con el transportista.'};
}
function xmlTag(xml:string,tag:string){return xml.match(new RegExp(`<${tag}(?:\\s[^>]*)?>([\\s\\S]*?)</${tag}>`,'i'))?.[1]?.trim()||'';}
export function amazonFeedResult(xml:string){
 const errors=xmlTag(xml,'MessagesWithError'),success=xmlTag(xml,'MessagesSuccessful');
 if(Number(errors)>0||/<ResultCode>\s*Error\s*<\/ResultCode>/i.test(xml))return {status:'rejected',message:xmlTag(xml,'ResultDescription')||'Amazon rechazó la cancelación.'};
 if(errors==='0'&&Number(success)>0)return {status:'confirmed',message:'Amazon procesó la cancelación.'};
 return {status:'unknown',message:'El informe de Amazon no confirma la cancelación.'};
}
export async function assertNoCancellation(admin:any,order:any){
 const result=await admin.from('order_cancellation_operations').select('id').eq('owner_id',order.owner_id).eq('order_id',order.id).in('status',['submitting','pending','unknown']).limit(1);
 if(result.error)throw result.error;if(result.data?.length)throw new Error('El pedido tiene una cancelación pendiente. Comprueba su resultado antes de generar o confirmar envíos.');
 const source=await admin.from('order_cancellation_operations').select('id').eq('owner_id',order.owner_id).eq('order_id',order.id).eq('kind','order').eq('status','confirmed').limit(1);
 if(source.error)throw source.error;if(source.data?.length||String(order.source_status||'').includes('cancel'))throw new Error('El pedido está cancelado.');
}
export async function claimOrderShipping(admin:any,order:any){
 const lease=crypto.randomUUID();const result=await admin.rpc('integration_claim_order_shipping',{p_order_id:order.id,p_owner_id:order.owner_id,p_lease:lease});
 if(result.error)throw result.error;if(!result.data)throw new Error('Hay otra operación de envío o cancelación en curso.');return {id:order.id,ownerId:order.owner_id,lease};
}
export async function releaseOrderShipping(admin:any,claim:any){if(claim)await admin.from('fulfillment_orders').update({order_action_lease:null,order_action_lease_until:null}).eq('id',claim.id).eq('owner_id',claim.ownerId).eq('order_action_lease',claim.lease);}

export function sanitizeAmazonError(value:unknown){
  const message=value instanceof Error?value.message:
    typeof value==='string'?value:
    value&&typeof value==='object'?(
      [((value as Record<string,unknown>).message),((value as Record<string,unknown>).details),((value as Record<string,unknown>).hint),((value as Record<string,unknown>).code)]
        .filter(part=>typeof part==='string'&&part.length>0).join(' | ')||JSON.stringify(value)
    ):String(value??'Error desconocido');
  return message
    .replace(/Atz[ar]\|[A-Za-z0-9._|\-]+/g,'[redacted-token]')
    .replace(/("?(?:client_secret|refresh_token|access_token)"?\s*[:=]\s*")([^"]+)(")/gi,'$1[redacted]$3')
    .slice(0,700);
}

export function sleep(ms:number){
  return new Promise<void>(resolve=>setTimeout(resolve,ms));
}

export function retryAfterMs(headers:Headers,attempt:number){
  const raw=headers.get('retry-after');
  const seconds=raw==null?NaN:Number(raw);
  if(Number.isFinite(seconds)&&seconds>=0)return Math.min(10_000,Math.max(100,seconds*1000));
  return Math.min(8_000,500*(2**attempt));
}

import { readAmazonSpApiCredentials, type AmazonSpApiCredentials } from './config.ts';
import { retryAfterMs, sanitizeAmazonError, sleep } from './http.ts';

const LWA_URL='https://api.amazon.com/auth/o2/token';
export const SP_API_BASE='https://sellingpartnerapi-eu.amazon.com';
export const MAX_ATTEMPTS=4;
const USER_AGENT='ZENVIA-Gestion/1.0 (Language=TypeScript; Platform=Supabase-Edge)';

type TokenCache={token:string;expiresAt:number};
const tokenCache=new Map<string,TokenCache>();

function amazonDate(date=new Date()){
  return date.toISOString().replace(/[:-]|\.\d{3}/g,'');
}

export async function getLwaAccessToken(credentials:AmazonSpApiCredentials=readAmazonSpApiCredentials()){
  const now=Date.now();
  const cacheKey=`${credentials.sellerId}:${credentials.clientId}:${credentials.refreshToken.slice(-12)}`;
  const cachedToken=tokenCache.get(cacheKey);
  if(cachedToken&&cachedToken.expiresAt>now+60_000)return cachedToken.token;
  const body=new URLSearchParams();
  body.set('grant_type','refresh_token');
  body.set('refresh_token',credentials.refreshToken);
  body.set('client_id',credentials.clientId);
  body.set('client_secret',credentials.clientSecret);
  const response=await fetch(LWA_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});
  const text=await response.text();
  let data:any=null;try{data=text?JSON.parse(text):null}catch{data=null}
  if(!response.ok||!data?.access_token){
    throw new Error(`Amazon LWA (${response.status}): ${sanitizeAmazonError(data?.error_description||data?.error||text)}`);
  }
  const expiresIn=Math.max(60,Number(data.expires_in)||3600);
  const next={token:String(data.access_token),expiresAt:now+(expiresIn*1000)};
  tokenCache.set(cacheKey,next);
  return next.token;
}

export type SpApiRequestOptions={
  method?:'GET'|'POST'|'PUT'|'DELETE';
  query?:Record<string,string|number|boolean|Array<string|number>|null|undefined>;
  body?:unknown;
  maxAttempts?:number;
};

function buildUrl(path:string,query?:SpApiRequestOptions['query']){
  const url=new URL(path.startsWith('http')?path:`${SP_API_BASE}${path.startsWith('/')?'':'/'}${path}`);
  for(const [key,value] of Object.entries(query||{})){
    if(value==null)continue;
    if(Array.isArray(value))url.searchParams.set(key,value.map(String).join(','));
    else url.searchParams.set(key,String(value));
  }
  return url;
}

function transient(status:number){return [429,500,502,503,504].includes(status);}

export async function spApiRequest<T=any>(path:string,options:SpApiRequestOptions={},credentials?:AmazonSpApiCredentials):Promise<T>{
  const url=buildUrl(path,options.query);
  for(let attempt=0;attempt<(options.maxAttempts||MAX_ATTEMPTS);attempt+=1){
    const accessToken=await getLwaAccessToken(credentials);
    const headers=new Headers({
      Accept:'application/json',
      'user-agent':USER_AGENT,
      'x-amz-access-token':accessToken,
      'x-amz-date':amazonDate(),
    });
    let body:BodyInit|undefined;
    if(options.body!==undefined){headers.set('Content-Type','application/json');body=JSON.stringify(options.body);}
    const response=await fetch(url,{method:options.method||'GET',headers,body,signal:AbortSignal.timeout(25000)});
    const text=await response.text();
    if(response.ok){
      if(!text)return undefined as T;
      try{return JSON.parse(text) as T}catch{throw new Error('Amazon SP-API devolvió una respuesta JSON no válida.');}
    }
    if(transient(response.status)&&attempt<(options.maxAttempts||MAX_ATTEMPTS)-1){
      await sleep(retryAfterMs(response.headers,attempt));
      continue;
    }
    let parsed:any=null;try{parsed=text?JSON.parse(text):null}catch{/* keep raw */}
    const detail=parsed?.errors?.map?.((item:any)=>item?.message||item?.code).filter(Boolean).join(' · ')||parsed?.message||text;
    throw new Error(`Amazon SP-API (${response.status}): ${sanitizeAmazonError(detail)}`);
  }
  throw new Error('Amazon SP-API agotó los reintentos.');
}

export type AmazonSpApiCredentials={
  clientId:string;
  clientSecret:string;
  refreshToken:string;
  sellerId:string;
};

function clean(value:unknown){return String(value??'').trim();}
function required(value:unknown,name:string){
  const text=clean(value);
  if(!text)throw new Error(`Falta ${name} en la configuración de Amazon SP-API.`);
  return text;
}
function parseEnv(){
  const raw=clean(Deno.env.get('AMAZON_SPAPI_CREDENTIALS'));
  if(!raw)return {} as any;
  try{return JSON.parse(raw)}catch{throw new Error('AMAZON_SPAPI_CREDENTIALS no contiene JSON válido.');}
}
function normalize(stored:any,env:any,fallbackSellerId=''):AmazonSpApiCredentials{
  const refreshToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!refreshToken)throw new Error('cuenta Amazon sin credenciales');
  return {
    // SP-API/LWA app credentials can be shared by every tenant using the same
    // registered application. Seller-specific credentials cannot.
    clientId:required(stored?.clientId||stored?.client_id||env?.clientId||env?.client_id,'client_id'),
    clientSecret:required(stored?.clientSecret||stored?.client_secret||env?.clientSecret||env?.client_secret,'client_secret'),
    refreshToken:refreshToken,
    sellerId:required(stored?.sellerId||stored?.seller_id||fallbackSellerId,'seller_id'),
  };
}

export function readAmazonSpApiCredentials():AmazonSpApiCredentials{
  throw new Error('cuenta Amazon sin credenciales');
}

async function readIntegrationSecret(admin:any,integrationAccountId:string,ownerId?:string|null){
  let query=admin.from('integration_accounts')
    .select('id,owner_id,external_account_id,secret_id,credential_source,status,enabled')
    .eq('id',integrationAccountId).eq('provider','amazon');
  if(ownerId)query=query.eq('owner_id',ownerId);
  const {data:integration,error}=await query.maybeSingle();
  if(error)throw error;
  if(!integration)throw new Error('La cuenta de integración de Amazon no existe.');
  if(integration.status==='disabled'||integration.enabled===false)throw new Error('La cuenta de Amazon está deshabilitada.');
  let stored:any={};
  if(integration.secret_id){
    const {data:secret,error:secretError}=await admin.rpc('integration_read_secret',{p_secret_id:integration.secret_id});
    if(secretError)throw secretError;
    try{stored=JSON.parse(String(secret||'{}'))}catch{throw new Error('Las credenciales cifradas de Amazon no tienen un formato válido.');}
  }
  return {integration,stored};
}

export async function loadAmazonSpApiCredentials(
  admin:any,
  options:{amazonAccountId?:string|null;integrationAccountId?:string|null;ownerId?:string|null}={},
):Promise<AmazonSpApiCredentials>{
  const env=parseEnv();
  const ownerId=clean(options.ownerId);
  let integrationAccountId=clean(options.integrationAccountId);
  let fallbackSellerId='';
  let accountOwnerId=ownerId;

  if(options.amazonAccountId){
    let accountQuery=admin.from('amazon_accounts')
      .select('seller_id,integration_account_id,owner_id')
      .eq('id',options.amazonAccountId);
    if(ownerId)accountQuery=accountQuery.eq('owner_id',ownerId);
    const {data:account,error}=await accountQuery.maybeSingle();
    if(error)throw error;
    if(!account)throw new Error('La cuenta Amazon asociada al trabajo ya no existe.');
    if(integrationAccountId&&integrationAccountId!==clean(account.integration_account_id)){
      throw new Error('La cuenta de integración no corresponde al trabajo de Amazon.');
    }
    accountOwnerId=clean(account.owner_id);
    fallbackSellerId=clean(account.seller_id);
    integrationAccountId=integrationAccountId||clean(account.integration_account_id);
  }

  if(!integrationAccountId){
    throw new Error('Amazon SP-API no está configurado para este workspace.');
  }

  const {integration,stored}=await readIntegrationSecret(admin,integrationAccountId,accountOwnerId||null);
  const ownToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!ownToken){
    // This allowlist contains integration_accounts.id, never a seller ID or a
    // caller-supplied workspace. The row above has already been owner-checked.
    const allowedId=clean(Deno.env.get('AMAZON_LEGACY_FALLBACK_ACCOUNT_ID'));
    const legacyToken=clean(env?.refreshToken)||clean(env?.refresh_token);
    if(!allowedId||clean(integration.id)!==allowedId||!legacyToken){
      throw new Error('cuenta Amazon sin credenciales');
    }
    const credentials=normalize({refreshToken:legacyToken},env,clean(integration.external_account_id)||fallbackSellerId);
    console.warn('amazon_legacy_fallback_used',{integration_account_id:integration.id,owner_id:integration.owner_id});
    return credentials;
  }
  return normalize(stored,env,clean(integration.external_account_id)||fallbackSellerId);
}
